/// <summary>
/// Minimal typed envelope for the GetCommand response. This is the only typed contract retained
/// from the original ~35-class contract graph; every other payload is navigated as a JObject.
/// </summary>
internal final class CELTCommandContract
{
    private str commandId;
    private str command;
    private str jobType;
    private str config;
    private str fileUrl;
}

Method.Source:
public str parmCommandId(str _commandId = commandId)
{
    commandId = _commandId;
    return commandId;
}

public str parmCommand(str _command = command)
{
    command = _command;
    return command;
}

public str parmJobType(str _jobType = jobType)
{
    jobType = _jobType;
    return jobType;
}

public str parmConfig(str _config = config)
{
    config = _config;
    return config;
}

public str parmFileUrl(str _fileUrl = fileUrl)
{
    fileUrl = _fileUrl;
    return fileUrl;
}
